def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'

    last_m, last_o = history[-1]
    opp_defects = sum(1 for _, o in history if o == 'D')

    if opp_defects > n * 0.8:
        return 'D'

    naive = (history[1][1] == 'C' and history[2][1] == 'C' and history[3][1] == 'C')
    if naive:
        if last_o == 'C':
            return 'D'

    if n == 99:
        return 'D'

    if n < 10:
        if last_o == 'D':
            if last_m == 'C':
                if rng.random() < 0.7:
                    return 'C'
            else:
                if rng.random() < 0.3:
                    return 'C'
            return 'D'
        return 'C'

    if n > 90:
        if opp_defects <= 2:
            return 'C'

    if last_o == 'C':
        return 'C'

    if n < 30:
        if opp_defects <= max(1, n // 10):
            return 'C'
        return 'D'

    if opp_defects > n * 0.3:
        return 'D'
    if opp_defects > n * 0.15:
        if last_m == 'D' and last_o == 'D':
            if n >= 2 and history[-2][1] == 'D':
                if rng.random() < 0.5:
                    return 'C'
        return 'D'
    return 'C'
